CREATE VIRTUAL TABLE t2 USING fts4(x,y,languageid=l); WITH RECURSIVE n(i) AS (VALUES(0) UNION ALL SELECT i+1 FROM n WHERE i<999),w(j,k) AS (VALUES('["zero","one","two","three","four","five","six","seven","eight","nine"]','["alpha","beta","gamma","delta","epsilon","zeta","eta","theta","iota","kappa"]')) INSERT INTO t2(docid,x,y,l) SELECT i,'zero '||(j->>((i/100)%10))||' '||(j->>((i/10)%10))||' '||(j->>(i%10)),'alpha '||(k->>((i/100)%10))||' '||(k->>((i/10)%10))||' '||(k->>(i%10)),i%9 FROM n,w; INSERT INTO t2(t2) VALUES('optimize');